<template>
 <div class="app-shell" :class="{'project-open':project&&!home}">
  <header><div class="brand"><span class="brand-mark"><StudioMark/></span><div>FURRYPATTERN <b>CAD</b><small>{{t.prototype}}</small></div></div><div class="project-title">{{startupState==='loading'?(language==='zh'?'正在读取项目…':localize('Loading projects…')):startupState==='failed'?(language==='zh'?'项目读取失败':localize('Projects could not be loaded')):home?(language==='zh'?'选择项目':localize('Choose a project')):(project?.name??t.noProject)}} <span v-if="project&&!home">/ R{{project.revision}}</span></div><select :value="locale" aria-label="Language" @change="setLocale(($event.target as HTMLSelectElement).value as Locale)"><option value="zh">简体中文</option><option value="en">English</option><option value="ja">日本語</option></select></header>
  <nav v-if="startupState==='ready'" class="project-toolbar" aria-label="Project commands"><button v-if="!home" :disabled="store.busy" @click="showHome">{{language==='zh'?'项目首页':localize('Projects')}}</button><button :disabled="store.busy" @click="requestMarkingLeave(()=>modal='new')">＋ {{t.new}}</button><button :disabled="store.busy" @click="openProject">↗ {{t.open}}</button><span class="separator"></span><button :disabled="home||!project||store.busy" @click="save()">{{t.save}} <kbd>Ctrl S</kbd></button><button :disabled="home||!project||store.busy" @click="save(true)">{{t.saveAs}}</button><span class="separator"></span><button :disabled="home||assistantOpen||(!store.data.canUndo&&!canUndoDraft)||store.busy" @click="undo()">↶ {{t.undo}}</button><button :disabled="home||assistantOpen||((!store.data.canRedo||committedRedoBlocked)&&!canRedoDraft)||store.busy" @click="undo(true)">↷ {{t.redo}}</button><div class="local-sessions"><button :disabled="store.busy" @click="showRecent=!showRecent">{{language==='zh'?'本地项目':localize('Local projects')}} · {{store.data.recent.length}} ▾</button><div v-if="showRecent" class="recent-list"><button v-for="r in store.data.recent" :key="r.sessionId" :disabled="store.busy" @click="activateSession(r.sessionId)">{{r.name}} <span>R{{r.revision}}</span></button></div></div><button :class="{active:assistantOpen}" :aria-pressed="assistantOpen" @click="assistantOpen=!assistantOpen">{{language==='zh'?'AI 助手':localize('AI assistant')}}</button><div class="spacer"></div><label class="ui-mode">{{language==='zh'?'界面模式':localize('Interface')}} <select v-model="advancedMode" aria-label="界面模式"><option :value="false">{{language==='zh'?'简单':localize('Simple')}}</option><option :value="true">{{language==='zh'?'高级':localize('Advanced')}}</option></select></label><button class="primary" :disabled="home||!project?.pieces.length||store.busy" @click="requestMarkingLeave(()=>{modal='export';warningsAck=false;})">{{t.export}} ↗</button></nav>
  <div v-if="store.error" class="error-banner" role="alert">{{t.error}} · {{label(store.error)}} <button @click="store.error=''">×</button></div>
  <TaskActivity :language="language"/>
  <main v-if="startupState!=='ready'" class="startup-state" :aria-busy="startupState==='loading'">
   <div v-if="startupState==='loading'" role="status" aria-live="polite"><span class="startup-spinner" aria-hidden="true"></span><h1>{{language==='zh'?'正在读取本地项目…':localize('Loading local projects…')}}</h1><p>{{language==='zh'?'请稍候，正在准备项目列表。':localize('Please wait while your project list is prepared.')}}</p></div>
   <div v-else role="alert"><h1>{{language==='zh'?'无法读取本地项目':localize('Local projects could not be loaded')}}</h1><p>{{language==='zh'?'请重试读取项目列表。':localize('Please try loading the project list again.')}}</p><button class="primary" @click="readInitialProjects">{{language==='zh'?'重新读取项目':localize('Retry loading projects')}}</button></div>
  </main>

  <div v-if="startupState==='ready'" class="studio-body">
  <nav v-if="project&&!home" class="workflow-nav" :aria-label="language==='zh'?'操作阶段':localize('Workflow')"><button v-for="(item,i) in stages" :key="item[0]" :data-stage="item[0]" :class="{active:stage===item[0]}" :aria-current="stage===item[0]?'step':undefined" @click="assistantOpen=false;stage=item[0] as Stage"><ToolIcon :name="stageIcons[item[0]]"/><span class="stage-number">{{i+1}}</span><span class="stage-label">{{item[1]}}</span></button><div class="spacer"></div><button class="activity-toggle" :aria-expanded="activityOpen" @click="activityOpen=!activityOpen">{{language==='zh'?'检查与记录':localize('Checks & activity')}} <b v-if="issues.length">{{issues.length}}</b> {{activityOpen?'⌄':'⌃'}}</button><AssistantConnection :language="language" compact/></nav>
  <AssistantPage v-if="startupState==='ready'&&assistantOpen" :language="language"/><main v-if="startupState==='ready'&&project&&!home" v-show="!assistantOpen" :class="['workspace','page-'+stage]">
   <GuidePage v-if="stage==='guide'" :language="language"/>
   <MarkingsPage v-if="visited.has('references')" v-show="stage==='references'" :key="sessionKey+'-extraction'" :language="language" :target-id="nodeTarget" @edit="openMarkingEditor" @select="selectedId=$event"/>
   <MarkingEditPage v-if="visited.has('marking-edit')" v-show="stage==='marking-edit'" ref="markingEditPage" :key="sessionKey+'-marking-edit'" :language="language" :target-id="markingEditTarget" :active="stage==='marking-edit'&&!assistantOpen&&!home" @references="stage='references'" @model="stage='model'" @select="selectedId=$event" @dirty="markingEditDirty=$event"/>
