   <MappingPage v-if="visited.has('mapping')" v-show="stage==='mapping'" :key="sessionKey+'-mapping'" :language="language" :target-id="nodeTarget" :selection="selectedMarking" @select="selectedId=$event" @edit="openMarkingEditor" @cutting="stage='cutting'"/>
