  </main>
  <main v-else-if="startupState==='ready'&&!assistantOpen" class="welcome"><div class="welcome-grid"></div><div class="welcome-content"><span class="eyebrow">FURRYPATTERN CAD / LOCAL FIRST</span><h1>{{t.welcome}}</h1><p>{{t.welcomeHint}}</p><div><button class="primary" :disabled="store.busy" @click="requestMarkingLeave(()=>modal='new')">＋ {{t.new}}</button><button :disabled="store.busy" @click="openProject">{{t.open}} ↗</button></div><section class="project-picker" aria-label="选择已有项目"><h2>{{language==='zh'?'已有项目':localize('Your projects')}}</h2><p v-if="!store.data.recent.length">{{language==='zh'?'还没有项目。新建项目或打开项目文件开始。':localize('Create a project or open a project file to begin.')}}</p><div v-for="r in store.data.recent" :key="r.sessionId" class="project-tile"><button :disabled="store.busy" class="project-card" :data-session-id="r.sessionId" @click="activateSession(r.sessionId)"><strong>{{r.name}}</strong><span>R{{r.revision}} · {{language==='zh'?'打开项目 →':localize('Open project →')}}</span></button><button class="delete-project" :data-delete-session-id="r.sessionId" :disabled="store.busy" :aria-label="(language==='zh'?'删除项目 ':localize('Delete project '))+r.name" :title="language==='zh'?'删除项目':localize('Delete project')" @click="requestDelete(r)"><ToolIcon name="delete"/></button></div><p v-if="deletedNotice" role="status">{{language==='zh'?'项目及其本地内容已删除。':localize('The project and its local contents have been deleted.')}}</p></section><small>{{t.prototype}}</small></div></main>
  </div>
<section v-if="project&&!home" v-show="activityOpen" class="bottom-panel activity-panel" aria-label="Checks and activity"><div class="tabs"><button v-for="key in (['diagnostics','jobs','history','recovery'] as const)" :key="key" :class="{active:tab===key}" @click="tab=key">{{t[key]}} <span v-if="key==='diagnostics'">{{issues.length}}</span></button></div><button class="activity-close" :aria-label="language==='zh'?'收起检查与记录':localize('Close activity')" @click="activityOpen=false">×</button><div class="tab-content"><JobsPanel v-if="tab==='jobs'" :language="language" @select="flowNavigate('pattern',$event)"/><template v-if="tab==='diagnostics'"><div v-if="!issues.length" class="valid-message">✓ {{t.noErrors}}</div><button v-for="issue in issues" :key="issue.ruleId" class="issue-row" @click="navigateIssue(issue)"><b :class="issue.severity">{{language==='zh'?(issue.severity==='error'?'错误':'警告'):(issue.severity==='error'?'Error':'Warning')}}</b><span>{{project.pieces.find(p=>p.id===issue.entityId)?.name}} · {{label(issue.messageKey)}}</span><span>↗</span></button></template><template v-if="tab==='history'"><div v-for="h in store.data.history" :key="h.revision" class="history-row"><span>R{{h.revision}}</span>{{h.type}}</div></template><template v-if="tab==='recovery'"><select v-model="recoveryRevision"><option v-for="r in store.data.recovery" :key="r" :value="r">Revision {{r}}</option></select><button :disabled="store.busy||!store.data.recovery.includes(recoveryRevision)" @click="restore">{{t.restore}}</button></template></div></section>
  <footer><span class="status-dot"></span>{{startupState==='loading'?(language==='zh'?'正在读取项目…':localize('Loading projects…')):startupState==='failed'?(language==='zh'?'项目读取失败':localize('Projects could not be loaded')):store.working?t.working:t.ready}}<span v-if="project&&!home">· {{t.local}} · R{{project.revision}}</span><div class="spacer"></div><span v-if="project&&!home">{{store.data.savedRevision===project.revision?t.saved:t.dirty}}</span><span>{{language==='zh'?'1 单位 = 1 毫米':localize('1 unit = 1 mm')}}</span></footer>
  <div v-if="pendingMarkingAction" class="marking-leave-backdrop"><section ref="markingLeaveDialog" class="marking-leave-dialog" role="dialog" aria-modal="true" :aria-label="language==='zh'?'花纹修改尚未保存':localize('Unsaved marking changes')"><h2>{{language==='zh'?'保存花纹修改后继续？':localize('Save marking changes before continuing?')}}</h2><p>{{language==='zh'?'当前花纹修改还在草稿中，尚未保存。':localize('The current marking changes are still an unsaved draft.')}}</p><div><button class="primary" :disabled="store.busy" @click="saveMarkingAndContinue">{{language==='zh'?'保存并继续':localize('Save and continue')}}</button><button :disabled="store.busy" @click="discardMarkingAndContinue">{{language==='zh'?'放弃修改并继续':localize('Discard changes and continue')}}</button><button :disabled="store.busy" @click="pendingMarkingAction=null">{{language==='zh'?'返回编辑':localize('Return to editing')}}</button></div></section></div>
  <div v-if="modal" class="modal-backdrop" @click.self="closeModal"><section ref="dialogElement" class="modal" role="dialog" aria-modal="true" :aria-label="modal==='delete'?(language==='zh'?'删除项目':localize('Delete project')):modal==='new'?t.createTitle:t.exportTitle"><button class="modal-close" :disabled="store.busy" @click="closeModal">×</button><template v-if="modal==='new'"><span class="eyebrow">PROJECT / 01</span><h2>{{t.createTitle}}</h2><label>{{t.projectName}}<input v-model="newName" autofocus maxlength="120" @keydown.enter="create"></label><p>mm · {{t.local}}</p><button class="primary" :disabled="!newName.trim()||store.busy" @click="create">{{t.create}} →</button></template><template v-else-if="modal==='delete'"><h2>{{language==='zh'?'删除项目？':localize('Delete project?')}}</h2><p><strong>{{deleteTarget?.name}}</strong> · R{{deleteTarget?.revision}}</p><p>{{language==='zh'?'将永久删除此项目在本软件中的本地内容、修改历史、恢复记录及不再使用的资源。此操作无法撤销。':localize('Permanently delete this project’s local contents, edit history, recovery records and unused resources. This cannot be undone.')}}</p><p>{{language==='zh'?'其他项目和单独保存或导出的项目文件不受影响。':localize('Other projects and separately saved or exported project files are retained.')}}</p><p v-if="store.error" role="alert">{{label(store.error)}}</p><div class="two-col"><button :disabled="store.busy" @click="closeModal">{{language==='zh'?'取消':localize('Cancel')}}</button><button class="confirm-delete" :disabled="store.busy" @click="deleteProject">{{language==='zh'?'永久删除':localize('Delete permanently')}}</button></div></template><template v-else><span class="eyebrow">OUTPUT / 1:1</span><h2>{{t.exportTitle}}</h2><p>{{t.exportHint}}</p><label v-if="project?.nesting" class="check-label"><input v-model="nestedExport" type="checkbox">{{language==='zh'?'使用已保存排料布局（过期或漏件会拒绝）':localize('Use saved nesting layout (stale/incomplete layouts rejected)')}}</label><label>{{language==='zh'?'PDF 纸张':localize('PDF paper')}}<select v-model="paperPreset"><option v-for="key in ['A4','A3','A2','A1','A0','Custom']" :key="key">{{key}}</option></select></label><div class="two-col"><label>{{language==='zh'?'纸宽 mm':localize('Width mm')}}<input v-model.number="paper.widthMm" type="number" min="130"></label><label>{{language==='zh'?'纸高 mm':localize('Height mm')}}<input v-model.number="paper.heightMm" type="number" min="80"></label><label>{{language==='zh'?'页边距 mm':localize('Margin mm')}}<input v-model.number="paper.marginMm" type="number" min="6"></label><label>{{language==='zh'?'重叠 mm':localize('Overlap mm')}}<input v-model.number="paper.overlapMm" type="number" min="0"></label></div><div class="export-warning">{{t.exportLimit}}</div><div v-for="issue in issues" :key="issue.ruleId" :class="['export-issue',issue.severity]">{{label(issue.messageKey)}}</div><label v-if="issues.some(i=>i.severity==='warning')" class="check-label"><input v-model="warningsAck" type="checkbox">{{t.confirmWarnings}}</label><div class="two-col"><button class="primary" :disabled="store.busy||issues.some(i=>i.severity==='error')||(issues.some(i=>i.severity==='warning')&&!warningsAck)" @click="exportFile('svg')">SVG ↗</button><button :disabled="store.busy||issues.some(i=>i.severity==='error')||(issues.some(i=>i.severity==='warning')&&!warningsAck)" @click="exportFile('pdf')">PDF · {{paperPreset}} ↗</button><button :disabled="store.busy||issues.some(i=>i.severity==='error')||(issues.some(i=>i.severity==='warning')&&!warningsAck)" @click="exportFile('png')">PNG · 144 DPI ↗</button><button :disabled="store.busy||issues.some(i=>i.severity==='error')||(issues.some(i=>i.severity==='warning')&&!warningsAck)" @click="exportFile('dxf')">DXF · mm ↗</button></div></template></section></div>
 </div>
</template>

<script setup lang="ts">
import {localize} from './localization';

import {computed,nextTick,onMounted,onUnmounted,provide,ref,shallowRef,useTemplateRef,watch} from 'vue';
import {useSession} from './store';
import {locale,setLocale,localizeRecord,type Locale} from './localization';
import AssistantPage from './AssistantPage.vue';
import AssistantConnection from './AssistantConnection.vue';
import ToolIcon from './ToolIcon.vue';
import StudioMark from './StudioMark.vue';
import JobsPanel from './JobsPanel.vue';
import TaskActivity from './TaskActivity.vue';
import GuidePage from './GuidePage.vue';
import MarkingsPage from './MarkingsPage.vue';
import MarkingEditPage from './MarkingEditPage.vue';
import ModelManagementPage from './ModelManagementPage.vue';
import MappingPage from './MappingPage.vue';
import CuttingPage from './CuttingPage.vue';
import PatternPage from './PatternPage.vue';
import AssemblyPage from './AssemblyPage.vue';
import ModelViewport from './ModelViewport.vue';
import PatternCanvas from './PatternCanvas.vue';
import {usePatternEditor} from './modules/usePatternEditor';
import {requestDraftHistory,canUndoDraft,canRedoDraft,clearDraftRedo,draftRecordedEvent} from './modules/useDraftHistory';
import {surfaceTransformsDirty,prepareSurfaceTransforms,saveSurfaceTransforms,discardSurfaceTransforms} from './modules/surfaceTransformDraftGuard';
import {useNativeDraftCloseGuard} from './modules/useNativeDraftCloseGuard';
import {nextHistoryStamp} from '../../../packages/ui/draft-history';
import {patternEditorKey} from './modules/patternEditorContext';
import {workflowTabs,isModelStage,type Stage,type PatternTab} from './modules/workflow-tabs';
import {messages,issueMessages} from './i18n';
import type {ExportFormat,Issue} from '../../../packages/schema/index';
const markingEditDirty=ref(false),markingEditTarget=ref(''),pendingMarkingAction=shallowRef<(()=>void)|null>(null),stageValue=ref<Stage>('references');
const stage=computed<Stage>({get:()=>stageValue.value,set:value=>{if(value!==stageValue.value)requestMarkingLeave(()=>{stageValue.value=value;});}});
const markingEditPage=useTemplateRef<InstanceType<typeof MarkingEditPage>>('markingEditPage'),markingLeaveDialog=useTemplateRef<HTMLElement>('markingLeaveDialog');
const store=useSession(),language=computed<'zh'|'en'>(()=>locale.value==='zh'?'zh':'en'),t=computed(()=>({...localizeRecord(messages[language.value]),jobs:language.value==='zh'?'计算任务':localize('Calculations')})),visited=ref(new Set<Stage>(['references'])),activityOpen=ref(false),tab=ref<'diagnostics'|'jobs'|'history'|'recovery'>('diagnostics'),productionTab=ref<PatternTab>('pieces'),nodeTarget=ref(''),recoveryRevision=ref(0),newName=ref(locale.value==='zh'?'未命名项目':locale.value==='ja'?'名称未設定のプロジェクト':localize('Untitled')),modal=ref<'new'|'export'|'delete'|null>(null),warningsAck=ref(false),nestedExport=ref(false),showRecent=ref(false);
const advancedMode=ref(false);provide('advancedMode',advancedMode);
const deleteTarget=ref<{sessionId:string;name:string;revision:number}>(),deletedNotice=ref(false);
function closeModal(){if(!store.busy)modal.value=null;}
function requestDelete(target:{sessionId:string;name:string;revision:number}){deleteTarget.value=target;store.error='';modal.value='delete';}
async function deleteProject(){const target=deleteTarget.value;if(!target)return;if(await store.run(()=>window.fpcad.deleteSession(target.sessionId))){await nextTick();home.value=true;modal.value=null;deleteTarget.value=undefined;showRecent.value=false;deletedNotice.value=true;await nextTick();document.querySelector<HTMLElement>('.project-picker button, .welcome-content button')?.focus();}}
const assistantOpen=ref(false);
const home=ref(true),startupState=ref<'loading'|'ready'|'failed'>('loading');let initialized=false,startupReadPending=false,startupReadTimer:ReturnType<typeof setTimeout>|undefined;
async function readInitialProjects(){
 if(startupReadPending)return;startupReadPending=true;startupState.value='loading';store.error='';
 const ok=await store.refresh(async()=>{try{return await Promise.race([window.fpcad.read(),new Promise<never>((_,reject)=>{startupReadTimer=setTimeout(()=>reject(new Error('Startup read timed out')),30000);})]);}finally{clearTimeout(startupReadTimer);startupReadTimer=undefined;}});
 startupReadPending=false;if(!ok){startupState.value='failed';return;}startupState.value='ready';await nextTick();initialized=true;fit();
}
watch(()=>[home.value,assistantOpen.value,stage.value,store.data.sessionId],()=>store.setErrorScope((store.data.sessionId??'none')+':'+(assistantOpen.value?'assistant':home.value?'home':stage.value)),{immediate:true,flush:'sync'});
const editor=usePatternEditor(language,stage,()=>{tab.value='jobs';activityOpen.value=true;});provide(patternEditorKey,editor);
const {project,selectedId,choiceIds,selected,selectedNode,tool,cancel,changeTool,finish,remove,fit,focusSelection,selectPiece,showChoices,mappedPoint,paperPreset,paper,issues}=editor;
const stageIcons:Record<string,string>={guide:'front',references:'color','marking-edit':'brushAdd',model:'solid',mapping:'node',cutting:'cut',assembly:'wireframe',pattern:'print'};
const stages=computed(()=>workflowTabs.map(s=>[s.id,language.value==='zh'?s.zh:localize(s.en)])),hasModel=computed(()=>isModelStage(stage.value)),modelTarget=computed(()=>hasModel.value?'#'+stage.value+'-viewport':'#preview-parking'),patternTarget=computed(()=>stage.value==='cutting'?'#cutting-pattern-viewport':stage.value==='pattern'?'#pattern-viewport':'#preview-parking');
const cutDraftActive=ref(false);
const selectedMarking=ref<{markingId:string;pieceId:string}>(),cutRequest=ref<{kind:'pen'|'paint';lineId?:string;token:number}>(),focusCut=ref(''),focusCutToken=ref(0);
function focusCutLine(id:string){focusCut.value=id;focusCutToken.value++;}
function drawCut(request:{kind:'pen'|'paint';lineId?:string}){cutRequest.value={...request,token:(cutRequest.value?.token??0)+1};}
function selectMarking(selection:{markingId:string;pieceId:string}){selectedMarking.value=selection;selectedId.value=selection.pieceId;stage.value='mapping';}
const sessionKey=computed(()=>store.data.sessionId??project.value?.id??'empty');
watch(()=>project.value?.markings,markings=>{if(selectedMarking.value&&!markings?.some(marking=>marking.id===selectedMarking.value?.markingId))selectedMarking.value=undefined;});
watch(sessionKey,()=>{visited.value=new Set<Stage>([stageValue.value]);if(initialized)home.value=false;cancel();selectedId.value='';selectedMarking.value=undefined;cutRequest.value=undefined;cutDraftActive.value=false;focusCut.value='';nodeTarget.value='';markingEditTarget.value='';markingEditDirty.value=false;pendingMarkingAction.value=null;warningsAck.value=false;modal.value=null;});
const modelPage=ref<InstanceType<typeof ModelManagementPage>>();
async function openModelSource(){if(store.busy||!project.value)return;visited.value.add('model');stage.value='model';await nextTick();modelPage.value?.openSource();}
function requestMarkingLeave(action:()=>void){prepareSurfaceTransforms();if(surfaceTransformsDirty.value||markingEditDirty.value){pendingMarkingAction.value=action;return;}action();}
function continueMarkingNavigation(){const action=pendingMarkingAction.value;pendingMarkingAction.value=null;action?.();}
function discardMarkingAndContinue(){if(store.busy)return;discardSurfaceTransforms();markingEditPage.value?.discard();markingEditDirty.value=false;continueMarkingNavigation();}
async function saveMarkingAndContinue(){if(store.busy)return;if(surfaceTransformsDirty.value&&!await saveSurfaceTransforms())return;if(markingEditDirty.value&&!await markingEditPage.value?.save())return;markingEditDirty.value=false;continueMarkingNavigation();}
useNativeDraftCloseGuard(()=>surfaceTransformsDirty.value||markingEditDirty.value,requestMarkingLeave);
function openMarkingEditor(id:string){requestMarkingLeave(()=>{markingEditTarget.value=id;stage.value='marking-edit';});}
watch(pendingMarkingAction,async value=>{if(value){await nextTick();markingLeaveDialog.value?.querySelector<HTMLButtonElement>('button')?.focus({preventScroll:true});}});
function label(key:string){return localize(issueMessages[key]?.[language.value==='zh'?0:1]??key);}
watch(stage,async value=>{visited.value.add(value);await nextTick();document.querySelector('.page-'+value+' .inspector')?.scrollTo({top:0});});
const committedPast:number[]=[],committedFuture:number[]=[],committedRedoBlocked=ref(false);
function draftRecorded(){if(store.data.canRedo)committedRedoBlocked.value=true;}
onMounted(()=>window.addEventListener(draftRecordedEvent,draftRecorded));onUnmounted(()=>window.removeEventListener(draftRecordedEvent,draftRecorded));
watch(()=>[sessionKey.value,project.value?.revision] as const,([id,revision],previous)=>{warningsAck.value=false;if(id!==previous?.[0]){committedPast.splice(0);committedFuture.splice(0);committedRedoBlocked.value=false;return;}if(revision===previous?.[1])return;const type=store.data.history[0]?.type;if(type==='undo'){committedFuture.push(committedPast.pop()??0);committedRedoBlocked.value=false;}else if(type==='redo')committedPast.push(committedFuture.pop()??0);else{committedPast.push(nextHistoryStamp());committedFuture.splice(0);committedRedoBlocked.value=false;clearDraftRedo();}},{flush:'sync'});
watch(tab,()=>{activityOpen.value=true;});
async function flowNavigate(key:Stage,id?:string,production?:'materials'|'seams'|'nesting'){if(surfaceTransformsDirty.value||stageValue.value==='marking-edit'&&markingEditDirty.value){requestMarkingLeave(()=>void flowNavigate(key,id,production));return;}stage.value=key;nodeTarget.value=id??'';if(key==='pattern')productionTab.value=production??'pieces';if(key==='pattern'&&id&&productionTab.value==='pieces')selectedId.value=id;if(key==='mapping'&&id){const m=project.value?.markings?.find(m=>m.id===id);if(m)selectedMarking.value={markingId:m.id,pieceId:m.paths[0]?.pieceId??''};}await nextTick();if(key==='pattern')focusSelection();}
async function navigateIssue(issue:Issue){assistantOpen.value=false;const id=issue.ruleId.split(':')[0];if(project.value?.markings?.some(m=>m.id===id)){await flowNavigate('mapping',id);selectedMarking.value={markingId:id,pieceId:issue.entityId};selectedId.value=issue.entityId;}else if(project.value?.seams?.some(s=>s.id===id)){selectedId.value=issue.entityId;await flowNavigate('pattern',id,'seams');}else await flowNavigate('pattern',issue.entityId);}
function showHome(){requestMarkingLeave(()=>{cancel();assistantOpen.value=false;showRecent.value=false;home.value=true;});}
let refreshTimer:ReturnType<typeof setTimeout>|undefined,unsubscribeChanged:(()=>void)|undefined,unsubscribeStorage:(()=>void)|undefined;
function scheduleRefresh(){clearTimeout(refreshTimer);refreshTimer=setTimeout(()=>{if(store.busy||startupState.value==='loading'){scheduleRefresh();return;}if(startupState.value==='ready')void store.refresh(()=>window.fpcad.read());},100);}
async function save(saveAs=false){if(!await saveSurfaceTransforms())return;if(stageValue.value==='marking-edit'&&markingEditDirty.value){if(!await markingEditPage.value?.save())return;await nextTick();}const p=project.value;if(p)await store.run(()=>window.fpcad.save(p.id,p.revision,saveAs));}
async function undo(redo=false){if(store.busy||assistantOpen.value||requestDraftHistory(redo,redo?(store.data.canRedo&&!committedRedoBlocked.value?committedFuture.at(-1)??0:undefined):(store.data.canUndo?committedPast.at(-1)??0:undefined)))return;if(redo&&committedRedoBlocked.value)return;editor.stopGesture();const p=project.value;if(p)await store.run(()=>redo?window.fpcad.redo(p.id,p.revision):window.fpcad.undo(p.id,p.revision));}
function documentHistory(e:Event){void undo((e as CustomEvent<{redo:boolean}>).detail?.redo??false);}
onMounted(()=>window.addEventListener('fpcad-document-history',documentHistory));onUnmounted(()=>window.removeEventListener('fpcad-document-history',documentHistory));
async function create(){if(!newName.value.trim()||store.busy)return;if(await store.run(()=>window.fpcad.create({name:newName.value.trim(),unit:'mm'}))){stage.value='references';assistantOpen.value=false;home.value=false;modal.value=null;selectedId.value='';cancel();}}
async function openProject(){if(surfaceTransformsDirty.value||stageValue.value==='marking-edit'&&markingEditDirty.value){requestMarkingLeave(()=>void openProject());return;}if(await store.run(()=>window.fpcad.open())){cancel();assistantOpen.value=false;home.value=false;selectedId.value='';fit();}}
async function activateSession(id:string){if(surfaceTransformsDirty.value||stageValue.value==='marking-edit'&&markingEditDirty.value){requestMarkingLeave(()=>void activateSession(id));return;}if(await store.run(()=>window.fpcad.activate(id))){cancel();assistantOpen.value=false;home.value=false;showRecent.value=false;selectedId.value='';fit();}}
async function exportFile(format:ExportFormat){const p=project.value;if(!p)return;const ack=warningsAck.value?issues.value.filter(i=>i.severity==='warning').map(i=>i.ruleId):[];if(await store.run(()=>window.fpcad.export(p.id,p.revision,format,ack,format==='pdf'?JSON.parse(JSON.stringify(paper.value)):undefined,nestedExport.value)))modal.value=null;}
async function restore(){if(surfaceTransformsDirty.value||stageValue.value==='marking-edit'&&markingEditDirty.value){requestMarkingLeave(()=>void restore());return;}const p=project.value;if(p)await store.run(()=>window.fpcad.restore(p.id,p.revision,recoveryRevision.value));}
watch(()=>store.data.recovery,revisions=>{if(!revisions.includes(recoveryRevision.value))recoveryRevision.value=revisions[0]??0;},{immediate:true});
const dialogElement=ref<HTMLElement>();let returnFocus:HTMLElement|null=null;
watch(modal,async value=>{if(value){returnFocus=document.activeElement instanceof HTMLElement?document.activeElement:null;await nextTick();dialogElement.value?.querySelector<HTMLElement>('input:not([type=checkbox]),select,button')?.focus();}else{await nextTick();if(returnFocus?.isConnected)returnFocus.focus();returnFocus=null;}});
function keyboard(e:KeyboardEvent){
 if(e.defaultPrevented)return;
 if(pendingMarkingAction.value){if(e.key==='Escape'){e.preventDefault();pendingMarkingAction.value=null;}else if(e.key==='Tab'){const buttons=Array.from(markingLeaveDialog.value?.querySelectorAll<HTMLButtonElement>('button:not([disabled])')??[]),first=buttons[0],last=buttons.at(-1);if(first&&(!markingLeaveDialog.value?.contains(document.activeElement)||e.shiftKey&&document.activeElement===first||!e.shiftKey&&document.activeElement===last)){e.preventDefault();(e.shiftKey?last:first)?.focus();}}return;}
 if(assistantOpen.value&&!modal.value)return;
 if(home.value&&!modal.value)return;
 if(document.querySelector('.print-preview-backdrop,.overview-backdrop'))return;
 if(modal.value){if(e.key==='Escape'){e.preventDefault();closeModal();}else if(e.key==='Tab'){const focusable=Array.from(dialogElement.value?.querySelectorAll<HTMLElement>('button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled]),[tabindex="0"]')??[]).filter(el=>el.getClientRects().length),first=focusable[0],last=focusable.at(-1);if(first&&(!dialogElement.value?.contains(document.activeElement)||e.shiftKey&&document.activeElement===first||!e.shiftKey&&document.activeElement===last)){e.preventDefault();(e.shiftKey?last:first)?.focus();}}return;}
 if(e.key==='Escape'){cancel();modal.value=null;return;}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();void save();return;}if(e.target instanceof Element&&e.target.closest('textarea,[contenteditable=true],input:not([type=number]):not([type=range]):not([type=checkbox]):not([type=radio]):not([type=color])'))return;if(e.ctrlKey||e.metaKey){if(e.key.toLowerCase()==='z'){e.preventDefault();void undo(e.shiftKey);}if(e.key.toLowerCase()==='y'){e.preventDefault();void undo(true);}return;}if(stage.value!=='pattern'||productionTab.value!=='pieces')return;if(e.key.toLowerCase()==='v')changeTool('select');if(e.key.toLowerCase()==='d')changeTool('measure');if(e.key==='Enter'&&tool.value==='polygon')void finish();if(e.key==='Delete')void remove();}
onMounted(async()=>{window.addEventListener('keydown',keyboard);window.addEventListener('blur',editor.stopGesture);unsubscribeChanged=window.fpcad.onChanged(scheduleRefresh);unsubscribeStorage=window.fpcad.onStorageError(()=>{store.error='RECOVERY_SAVE_FAILED';});await readInitialProjects();});
onUnmounted(()=>{window.removeEventListener('keydown',keyboard);window.removeEventListener('blur',editor.stopGesture);unsubscribeChanged?.();unsubscribeStorage?.();clearTimeout(refreshTimer);clearTimeout(startupReadTimer);});
</script>

